const money=(cents:number)=>(cents/100).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});

type CatalogOption={id?:number;name?:string;slug?:string;size?:string;product_count:number;has_sizes?:number};
type FilterProduct={id:number;category_slug:string;brand_slug:string;price_cents:number;featured:number;on_sale:number;is_new:number;sizes:string[];sizes_csv?:string};
type CatalogData={brands:CatalogOption[];categories:CatalogOption[];sizes:CatalogOption[];filter_products:FilterProduct[]};
type AccountData={customer:{id:number;name:string;email:string;cpf?:string;phone?:string};addresses:{id:number;label:string;zip_code:string;street:string;number:string;complement?:string;district:string;city:string;state:string;is_default:number}[];coupons:{id:number;code:string;description:string;discount_type:string;discount_value:number;min_order_cents:number;ends_at?:string}[];orders:{id:number;order_number:string;status:string;total_cents:number;created_at:string;product_name:string;variant_name:string;image_url?:string}[];summary:{orders:number;in_transit:number;addresses:number}};

const priceLimits=[500,750,1000,1500,3000];
function matchingProducts(catalog:CatalogData,filters:{category?:string;brand?:string;size?:string;maxPrice?:string}) {
  return catalog.filter_products.filter(product=>(!filters.category||product.category_slug===filters.category)&&(!filters.brand||product.brand_slug===filters.brand)&&(!filters.size||product.sizes.includes(filters.size))&&(!filters.maxPrice||product.price_cents<=Number(filters.maxPrice)*100));
}
function relevantPrices(productsIndex:FilterProduct[]) {
  return priceLimits.map(limit=>({limit,count:productsIndex.filter(product=>product.price_cents<=limit*100).length})).filter((item,index,items)=>item.count>0&&(index===0||item.count!==items[index-1].count));
}

function useCatalog(query="") {
  const [catalog,setCatalog]=useState<CatalogData>({brands:[],categories:[],sizes:[],filter_products:[]});
  useEffect(()=>{const controller=new AbortController();fetch(`/api/catalog?q=${encodeURIComponent(query)}`,{signal:controller.signal}).then(r=>r.ok?r.json():Promise.reject()).then(({data})=>setCatalog({...data,filter_products:data.filter_products.map((product:FilterProduct)=>({...product,sizes:product.sizes_csv?product.sizes_csv.split("|"):[]}))})).catch(()=>{});return()=>controller.abort();},[query]);
  return catalog;
}
function useAccount(){const {authFetch,user}=useAuth();const [data,setData]=useState<AccountData|null>(null);useEffect(()=>{if(!user)return;const controller=new AbortController();authFetch("/api/account",{signal:controller.signal}).then(response=>response.ok?response.json():Promise.reject()).then(payload=>setData(payload.data)).catch(()=>{});return()=>controller.abort();},[user]);return data;}

export function StorePage({ path }: { path: string }) {
  if (path === "/admin/login") return <AdminLogin/>;
  if (path.startsWith("/admin")) return <AdminPage path={path}/>;
  if (path.startsWith("/checkout")) return <CheckoutPage path={path}/>;
  return <><Header/><main>{resolveStorePage(path)}</main><Footer/></>;
}

function useApiProducts(limit=12, query="") {
  const [items,setItems]=useState<Product[]>([]);
  useEffect(()=>{const controller=new AbortController();fetch(`/api/products?limit=${limit}${query}`,{signal:controller.signal}).then(r=>r.ok?r.json():Promise.reject()).then(({data})=>setItems(data.items.map(mapApiProduct))).catch(()=>{});return()=>controller.abort();},[limit,query]);
  return items;
}

type ApiProduct={id:number;slug:string;brand:string;name:string;price_cents:number;compare_at_cents?:number;image_url?:string;featured:number;photographer?:string;category?:string;sizes_csv?:string;available_stock?:number};
const mapApiProduct=(p:ApiProduct):Product=>({id:p.id,slug:p.slug,brand:p.brand,name:p.name,price:money(p.price_cents),oldPrice:p.compare_at_cents?money(p.compare_at_cents):undefined,tone:"from-zinc-950 to-zinc-700",tag:p.featured?"DESTAQUE":undefined,image:p.image_url,photographer:p.photographer,priceCents:p.price_cents,compareAtCents:p.compare_at_cents,category:p.category,sizes:p.sizes_csv?p.sizes_csv.split("|"):[],availableStock:p.available_stock});
function usePaginatedProducts(query:string){
  const [request,setRequest]=useState({query,page:1});
  const [result,setResult]=useState({query,items:[] as Product[],pages:1,total:0});
  const [loading,setLoading]=useState(true);
  const page=request.query===query?request.page:1;
  if(request.query!==query)setRequest({query,page:1});
  useEffect(()=>{
    const controller=new AbortController();setLoading(true);
    fetch(`/api/products?limit=12&page=${page}${query}`,{signal:controller.signal})
      .then(response=>response.ok?response.json():Promise.reject())
      .then(({data})=>{if(!controller.signal.aborted)setResult(current=>({query,items:page===1||current.query!==query?data.items.map(mapApiProduct):[...current.items,...data.items.map(mapApiProduct)],pages:data.pagination.pages,total:data.pagination.total}));})
      .catch(()=>{}).finally(()=>{if(!controller.signal.aborted)setLoading(false);});
    return()=>controller.abort();
  },[page,query]);
  const current=result.query===query;
  return {items:current?result.items:[],total:current?result.total:0,loading:loading||!current,hasMore:current&&page<result.pages,loadMore:()=>setRequest({query,page:page+1})};
}

type HeroSlide={id:string;badge?:string;title:string;description:string;image_url:string;mobile_image_url?:string;cta_label:string;cta_url:string;secondary_label?:string;secondary_url?:string};
const fallbackHeroSlides:HeroSlide[]=[
  {id:"fallback-1",badge:"Seleção Ridekit",title:"Proteção para cada rota.",description:"Capacetes, equipamentos e acessórios com procedência, garantia e suporte especializado.",image_url:"https://images.unsplash.com/photo-1558981806-ec527fa84c39?auto=format&fit=crop&w=1600&q=82",cta_label:"Ver capacetes",cta_url:"/capacetes",secondary_label:"Ofertas da semana",secondary_url:"/ofertas"},
  {id:"fallback-2",badge:"Frete e condições",title:"Seu próximo equipamento começa aqui.",description:"Frete grátis acima de R$ 299, parcelamento em até 10x e 5% de desconto no Pix.",image_url:"https://images.unsplash.com/photo-1558981359-219d6364c9c8?auto=format&fit=crop&w=1600&q=82",cta_label:"Explorar a loja",cta_url:"/capacetes",secondary_label:"Guia de tamanho",secondary_url:"/guia-de-tamanho"},
  {id:"fallback-3",badge:"Novidades",title:"Pilotagem com mais confiança.",description:"Encontre o tamanho certo, acompanhe seu pedido e conte com atendimento humano quando precisar.",image_url:"https://images.unsplash.com/photo-1705162815217-d01650b9c542?auto=format&fit=crop&w=1600&q=82",cta_label:"Conhecer produtos",cta_url:"/capacetes"},
];
function HomeHero() {
  const [configured,setConfigured]=useState<HeroSlide[]|null>(null);
  useEffect(()=>{const controller=new AbortController();fetch("/api/hero-slides",{signal:controller.signal}).then(response=>response.ok?response.json():Promise.reject()).then(body=>setConfigured(body.data.items.map((slide:any)=>({...slide,id:String(slide.id)})))).catch(()=>setConfigured([]));return()=>controller.abort();},[]);
  const slides=configured?.length?configured:fallbackHeroSlides;
  const [active,setActive]=useState(0);
  const [paused,setPaused]=useState(false);
  const total=slides.length;
  useEffect(()=>{if(paused||total<2)return;const timer=window.setInterval(()=>setActive(current=>(current+1)%total),5500);return()=>window.clearInterval(timer);},[paused,total]);
  useEffect(()=>{if(active>=total)setActive(0);},[active,total]);
  if(!total)return null;
  const current=slides[active];
  const go=(direction:number)=>setActive(index=>(index+direction+total)%total);
  return <section
    className="container-page relative mt-4 min-h-[540px] overflow-hidden rounded-t-3xl bg-dark text-white md:mt-8 md:min-h-[600px]"
    aria-roledescription="carrossel"
    aria-label="Ofertas em destaque"
    onMouseEnter={()=>setPaused(true)} onMouseLeave={()=>setPaused(false)}
    onFocusCapture={()=>setPaused(true)} onBlurCapture={()=>setPaused(false)}
  >
    {slides.map((slide,index)=><picture key={slide.id}><source media="(max-width: 767px)" srcSet={slide.mobile_image_url||slide.image_url}/><img src={slide.image_url} alt="" aria-hidden="true" className={`absolute inset-0 size-full object-cover transition-opacity duration-700 ${index===active?"opacity-100":"opacity-0"}`}/></picture>)}
    <div className="absolute inset-0 bg-[linear-gradient(90deg,rgba(5,7,9,.94)_0%,rgba(5,7,9,.76)_42%,rgba(5,7,9,.18)_78%),linear-gradient(0deg,rgba(5,7,9,.72)_0%,transparent_52%)]"/>
    <div className="relative z-10 flex min-h-[540px] flex-col justify-end p-7 pb-24 md:min-h-[600px] md:justify-center md:p-14">
      <div key={current.id} className="hero-content-in max-w-[680px]">
        {current.badge&&<p className="mb-5 text-xs font-bold uppercase tracking-[.2em] text-accent">{current.badge}</p>}
        <h1 className="max-w-2xl text-[40px] font-semibold uppercase leading-[.94] tracking-[-.05em] md:text-6xl">{current.title}</h1>
        <p className="mt-6 max-w-lg text-sm leading-6 text-[#d7dbe0] md:text-base">{current.description}</p>
        <div className="mt-8 flex flex-wrap gap-3"><Button href={current.cta_url}>{current.cta_label} <ArrowRight size={17}/></Button>{current.secondary_label&&current.secondary_url&&<Button href={current.secondary_url} variant="outline" className="border-white/30 bg-white/10 text-white hover:border-white hover:bg-white/20">{current.secondary_label}</Button>}</div>
      </div>
    </div>
    <div className="absolute bottom-6 left-7 z-20 flex items-center gap-2 md:left-14">{slides.map((slide,index)=><button key={slide.id} onClick={()=>setActive(index)} aria-label={`Ir para oferta ${index+1}`} aria-current={index===active?"true":undefined} className={`h-1.5 rounded-full transition-all ${index===active?"w-8 bg-accent":"w-3 bg-white/45 hover:bg-white"}`}/>)}</div>
    <div className="absolute bottom-5 right-6 z-20 flex gap-2 md:bottom-8 md:right-10"><button onClick={()=>go(-1)} aria-label="Oferta anterior" className="focus-ring grid size-11 place-items-center rounded-xl border border-white/20 bg-black/30 backdrop-blur-sm transition hover:bg-white hover:text-dark"><ArrowLeft size={18}/></button><button onClick={()=>go(1)} aria-label="Próxima oferta" className="focus-ring grid size-11 place-items-center rounded-xl border border-white/20 bg-black/30 backdrop-blur-sm transition hover:bg-white hover:text-dark"><ArrowRight size={18}/></button></div>
  </section>;
}

function HomeFinder() {
  const catalog=useCatalog();
  const [category,setCategory]=useState(""); const [size,setSize]=useState(""); const [brand,setBrand]=useState(""); const [maxPrice,setMaxPrice]=useState("");
  const categoryProducts=matchingProducts(catalog,{category});
  const brandOptions=catalog.brands.filter(item=>categoryProducts.some(product=>product.brand_slug===item.slug));
  const sizeProducts=matchingProducts(catalog,{category,brand});
  const sizeOptions=catalog.sizes.map(item=>({...item,available:sizeProducts.filter(product=>product.sizes.includes(item.size||"")).length})).filter(item=>item.available>0);
  const sizeDisabled=sizeOptions.length===0;
  const priceProducts=matchingProducts(catalog,{category,brand,size}); const priceOptions=relevantPrices(priceProducts);
  const resultCount=matchingProducts(catalog,{category,brand,size,maxPrice}).length;
  const chooseCategory=(value:string)=>{setCategory(value);setBrand("");setSize("");setMaxPrice("");};
  const chooseBrand=(value:string)=>{setBrand(value);setSize("");setMaxPrice("");};
  const chooseSize=(value:string)=>{setSize(value);setMaxPrice("");};
  const params=new URLSearchParams(); if(category)params.set("category",category); if(size)params.set("size",size); if(brand)params.set("brand",brand); if(maxPrice)params.set("max_price",maxPrice);
  const href=`/capacetes${params.size?`?${params.toString()}`:""}`;
  return <section className="container-page relative z-10 -mt-2 rounded-b-[20px] border border-line bg-white p-5 md:-mt-4 md:p-6"><div className="grid gap-4 md:grid-cols-[repeat(4,1fr)_auto]">
    <label className="text-xs font-semibold">Tipo<select value={category} onChange={e=>chooseCategory(e.target.value)} className="mt-2 h-12 w-full rounded-xl border border-line px-3 text-sm font-normal text-muted"><option value="">Todos os tipos</option>{catalog.categories.map(item=><option value={item.slug} key={item.slug}>{item.name} ({item.product_count})</option>)}</select></label>
    <label className="text-xs font-semibold">Marca<select value={brand} onChange={e=>chooseBrand(e.target.value)} className="mt-2 h-12 w-full rounded-xl border border-line px-3 text-sm font-normal text-muted"><option value="">Todas as marcas ({categoryProducts.length})</option>{brandOptions.map(item=>{const count=categoryProducts.filter(product=>product.brand_slug===item.slug).length;return <option value={item.slug} key={item.slug}>{item.name} ({count})</option>;})}</select></label>
    <label className={`text-xs font-semibold ${sizeDisabled?"text-muted":""}`}>Tamanho<select disabled={sizeDisabled} value={sizeDisabled?"":size} onChange={e=>chooseSize(e.target.value)} className="mt-2 h-12 w-full rounded-xl border border-line px-3 text-sm font-normal text-muted disabled:cursor-not-allowed disabled:bg-canvas disabled:opacity-60"><option value="">{sizeDisabled?"Não se aplica":"Todos os tamanhos"}</option>{sizeOptions.map(item=><option value={item.size} key={item.size}>{item.size} ({item.available})</option>)}</select></label>
    <label className="text-xs font-semibold">Preço<select disabled={priceOptions.length===0} value={maxPrice} onChange={e=>setMaxPrice(e.target.value)} className="mt-2 h-12 w-full rounded-xl border border-line px-3 text-sm font-normal text-muted disabled:cursor-not-allowed disabled:bg-canvas disabled:opacity-60"><option value="">Qualquer preço ({priceProducts.length})</option>{priceOptions.map(item=><option value={item.limit} key={item.limit}>Até {item.limit.toLocaleString("pt-BR",{style:"currency",currency:"BRL",maximumFractionDigits:0})} ({item.count})</option>)}</select></label>
    <Button href={href} className="self-end">{catalog.filter_products.length?`Ver ${resultCount} ${resultCount===1?"produto":"produtos"}`:"Carregando…"}</Button>
  </div></section>;
}

function CatalogControls({basePath,catalog}:{basePath:string;catalog:CatalogData}) {
  const router=useRouter(); const searchParams=useSearchParams();
  const category=searchParams.get("category")||""; const brand=searchParams.get("brand")||""; const size=searchParams.get("size")||"";
  const sourceProducts=basePath==="/ofertas"?catalog.filter_products.filter(product=>product.on_sale):basePath==="/lancamentos"?catalog.filter_products.filter(product=>product.is_new):catalog.filter_products;
  const facetCatalog={...catalog,filter_products:sourceProducts};
  const maxPrice=searchParams.get("max_price")||"";
  const categoriesProducts=matchingProducts(facetCatalog,{brand,size,maxPrice});
  const categoryProducts=matchingProducts(facetCatalog,{category,size,maxPrice});
  const brandOptions=catalog.brands.filter(item=>item.slug===brand||categoryProducts.some(product=>product.brand_slug===item.slug));
  const sizeProducts=matchingProducts(facetCatalog,{category,brand,maxPrice});
  const sizeOptions=catalog.sizes.map(item=>({...item,available:sizeProducts.filter(product=>product.sizes.includes(item.size||"")).length})).filter(item=>item.available>0||item.size===size);
  const sizeDisabled=sizeOptions.length===0&&!size;
  const priceProducts=matchingProducts(facetCatalog,{category,brand,size});
  const priceOptions=relevantPrices(priceProducts);
  if(maxPrice&&!priceOptions.some(item=>item.limit===Number(maxPrice)))priceOptions.push({limit:Number(maxPrice),count:priceProducts.filter(product=>product.price_cents<=Number(maxPrice)*100).length});
  const change=(key:string,value:string)=>{const next=new URLSearchParams(searchParams.toString());if(value)next.set(key,value);else next.delete(key);router.push(`${basePath}${next.size?`?${next.toString()}`:""}`);};
  const selectClass="h-11 w-full rounded-xl border border-line bg-white px-3 text-sm text-muted";
  return <div className="mb-6 grid gap-3 rounded-2xl border border-line bg-white p-4 sm:grid-cols-2 lg:grid-cols-5">
    <select aria-label="Filtrar por categoria" value={category} onChange={e=>change("category",e.target.value)} className={selectClass}><option value="">Todas as categorias ({categoriesProducts.length})</option>{catalog.categories.filter(item=>item.slug===category||categoriesProducts.some(product=>product.category_slug===item.slug)).map(item=>{const count=categoriesProducts.filter(product=>product.category_slug===item.slug).length;return <option value={item.slug} key={item.slug}>{item.name} ({count})</option>;})}</select>
    <select aria-label="Filtrar por marca" value={brand} onChange={e=>change("brand",e.target.value)} className={selectClass}><option value="">Todas as marcas ({categoryProducts.length})</option>{brandOptions.map(item=>{const count=categoryProducts.filter(product=>product.brand_slug===item.slug).length;return <option value={item.slug} key={item.slug}>{item.name} ({count})</option>;})}</select>
    <select aria-label="Filtrar por tamanho" disabled={sizeDisabled} value={sizeDisabled?"":size} onChange={e=>change("size",e.target.value)} className={`${selectClass} disabled:cursor-not-allowed disabled:bg-canvas disabled:opacity-60`}><option value="">{sizeDisabled?"Tamanho não aplicável":`Todos os tamanhos (${sizeProducts.length})`}</option>{sizeOptions.map(item=><option value={item.size} key={item.size}>{item.size} ({item.available})</option>)}</select>
    <select aria-label="Filtrar por preço" disabled={priceOptions.length===0} value={searchParams.get("max_price")||""} onChange={e=>change("max_price",e.target.value)} className={`${selectClass} disabled:cursor-not-allowed disabled:bg-canvas disabled:opacity-60`}><option value="">Qualquer preço ({priceProducts.length})</option>{priceOptions.map(item=><option value={item.limit} key={item.limit}>Até {item.limit.toLocaleString("pt-BR",{style:"currency",currency:"BRL",maximumFractionDigits:0})} ({item.count})</option>)}</select>
    <select aria-label="Ordenar produtos" value={searchParams.get("sort")||""} onChange={e=>change("sort",e.target.value)} className={selectClass}><option value="">Mais relevantes</option><option value="price_asc">Menor preço</option><option value="price_desc">Maior preço</option><option value="rating">Melhor avaliados</option><option value="newest">Mais recentes</option></select>
    {searchParams.size>0&&<Link href={basePath} className="text-xs font-semibold text-accent sm:col-span-2 lg:col-span-5">Limpar filtros</Link>}
  </div>;
}

function resolveStorePage(path:string) {
  if (path === "/") return <HomePage/>;
  if (path === "/capacetes" || path === "/busca" || path === "/ofertas" || path === "/lancamentos") return <CatalogPage path={path}/>;
  if (path === "/categorias") return <CategoriesPage/>;
  if (path.startsWith("/produto/")) return <ProductPage slug={path.split("/").pop()||""}/>;
  if (path === "/carrinho") return <CartPage/>;
  if (path === "/conta-encerrada") return <AccountClosed/>;
  if (path === "/login") return <AuthScreen/>;
  if (path === "/recuperar-senha") return <PasswordRecovery/>;
  if (path === "/redefinir-senha") return <PasswordRecovery reset/>;
  if (path === "/marcas" || path.startsWith("/marcas/")) return <BrandsPage slug={path.split("/")[2]||""}/>;
  if (path.startsWith("/conta")) return <AccountPage path={path}/>;
  if(path==="/privacidade"||path==="/termos")return <LegalPage kind={path==="/privacidade"?"privacy":"terms"}/>;
  if (["/sobre","/contato","/entrega","/garantia","/guia-de-tamanho","/ajuda","/ajuda/devolucoes"].includes(path)) return <ContentPage path={path}/>;
  if (path === "/mapa") return <RouteMapPage/>;
  return <NotFoundPage/>;
}

