  const chooseAddress=(value:SavedCheckoutAddress)=>{setSelectedAddress(value);setCheckoutError("");sessionStorage.setItem("ridekit-checkout-address",JSON.stringify({...value,customer_id:user?.id}));};
  if(step==="pix")return <CheckoutStatus type="pix"/>; if(step==="erro")return <CheckoutStatus type="erro"/>; if(step==="sucesso")return <CheckoutStatus type="sucesso"/>;
  const title={checkout:"Revise seu carrinho",identificacao:"Identificação",endereco:"Endereço de entrega",entrega:"Escolha a entrega",pagamento:"Escolha como pagar"}[step||"checkout"];
  const shippingCents=shipping==="Retirada"||subtotal>=settings.free_shipping_threshold_cents?0:shippingQuote?.key===quoteKey?shippingQuote.cents:shipping==="Expressa"?settings.express_shipping_cents:settings.standard_shipping_cents;
  const selectedCoupon=checkoutCoupon(cart,shippingCents,settings.pix_discount_percent),couponReduction=couponDiscount(selectedCoupon,selectedCoupon?.eligible_subtotal_cents||0,shippingCents,subtotal),pixDiscount=Math.round((subtotal-couponReduction.productCents)*settings.pix_discount_percent/100);
